import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))

            friends_pos = []
            for _ in range(k):
                friends_pos.append(int(next(iterator)))

            adj = [[] for _ in range(n + 1)]
            for _ in range(n - 1):
                u = int(next(iterator))
                v = int(next(iterator))
                adj[u].append(v)
                adj[v].append(u)

            friend_set = set(friends_pos)

            dist_vlad = [-1] * (n + 1)
            dist_friend = [-1] * (n + 1)

            queue = [1]
            dist_vlad[1] = 0

            q_idx = 0
            while q_idx < len(queue):
                u = queue[q_idx]
                q_idx += 1

                d = dist_vlad[u]

                for v in adj[u]:
                    if dist_vlad[v] == -1:
                        dist_vlad[v] = d + 1
                        queue.append(v)

            queue = list(friend_set)
            for f in queue:
                dist_friend[f] = 0

            q_idx = 0
            while q_count := q_idx < len(queue):
                if q_idx >= len(queue):
                    break
                u = queue[q_idx]
                q_idx += 1
                d = dist_friend[u]

                for v in adj[u]:
                    if dist_friend[v] == -1:
                        dist_friend[v] = d + 1
                        queue.append(v)


            def get_leaf_count(node, parent, d_vlad):
                if dist_friend[node] != -1 and dist_friend[node] <= d_vlad:
                    return 0

                is_leaf = True
                count = 0

                for neighbor in adj[node]:
                    if neighbor != parent:
                        is_leaf = False
                        count += get_leaf_count(neighbor, node, d_vlad + 1)

                if is_leaf:
                    return 1

                return count

            if 1 in friend_set:
                results.append("-1")
                continue

            blocked_count = 0

            def dfs(node, parent, d_vlad):
                nonlocal blocked_count

                if dist_friend[node] != -1 and dist_friend[node] <= dist_vlad[node]:
                    return 0

                is_leaf = True
                total_needed = 0

                for neighbor in adj[node]:
                    if neighbor == parent:
                        continue
                    is_leaf = False
                    total_needed += dfs(neighbor, node, d_vlad + 1)

                return total_needed if not is_leaf else 1

            needed = dfs(1, 0, 0)

            if needed == 0:
                results.append("-1")
            else:
                results.append(str(needed))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
